"""Check every configured feed and write the JSON report."""

import json
from collections.abc import Callable, Sequence
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path

from feedcheck.config import Config, FeedConfig
from feedcheck.fetch import fetch_with_retries
from feedcheck.health import Status, Verdict, judge

REPORT_INDENT = "  "


@dataclass(frozen=True)
class FeedResult:
    feed: FeedConfig
    verdict: Verdict
    duration_seconds: float


@dataclass(frozen=True)
class Clocks:
    """Time sources, injected so tests can control them."""

    sleep: Callable[[float], None]
    monotonic: Callable[[], float]
    now: Callable[[], datetime]


def check_feed(feed: FeedConfig, config: Config, clocks: Clocks) -> FeedResult:
    started = clocks.monotonic()
    outcome = fetch_with_retries(
        feed.url,
        timeout_seconds=config.timeout_seconds,
        attempts=config.attempts,
        retry_delay_seconds=config.retry_delay_seconds,
        sleep=clocks.sleep,
    )
    verdict = judge(outcome, feed.max_age_hours, clocks.now())
    return FeedResult(feed=feed, verdict=verdict, duration_seconds=clocks.monotonic() - started)


def check_feeds(config: Config, clocks: Clocks) -> tuple[FeedResult, ...]:
    results = tuple(check_feed(feed, config, clocks) for feed in config.feeds)
    if len(results) != len(config.feeds):
        raise AssertionError(f"checked {len(results)} feeds, configured {len(config.feeds)}")
    return results


def all_healthy(results: Sequence[FeedResult]) -> bool:
    return all(result.verdict.status is Status.HEALTHY for result in results)


def build_report(results: Sequence[FeedResult], checked_at: datetime) -> dict[str, object]:
    return {
        "checked_at": checked_at.isoformat(),
        "healthy": all_healthy(results),
        "feeds": [
            {
                "name": result.feed.name,
                "url": result.feed.url,
                "status": result.verdict.status.value,
                "reason": result.verdict.reason,
                "items": result.verdict.item_count,
                "duration_seconds": result.duration_seconds,
            }
            for result in results
        ],
    }


def write_report(report: dict[str, object], path: Path) -> None:
    path.write_text(json.dumps(report, indent=REPORT_INDENT) + "\n", encoding="utf-8")
EOF
cat > feedcheck/cli.py <<'EOF'
"""Command line entry point: feedcheck --config feeds.toml --output report.json"""

import argparse
import sys
import time
from collections.abc import Sequence
from datetime import UTC, datetime
from pathlib import Path

from feedcheck.check import Clocks, all_healthy, build_report, check_feeds, write_report
from feedcheck.config import ConfigError, load_config

EXIT_ALL_HEALTHY = 0
EXIT_NOT_ALL_HEALTHY = 1


def _utc_now() -> datetime:
    return datetime.now(UTC)


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="feedcheck", description="Check that JSON feeds are healthy and write a report.")
    parser.add_argument("--config", required=True, type=Path, help="TOML file listing the feeds and fetch settings")
    parser.add_argument("--output", required=True, type=Path, help="where to write the JSON report")
    return parser


def main(argv: Sequence[str]) -> int:
    if sys.flags.optimize:
        raise SystemExit("feedcheck: do not run with python -O: invariants are asserts")
    args = _parser().parse_args(argv)
    # Boundary (declared in .shockharness.toml): an invalid config stops the tool before any fetch.
    try:
        config = load_config(args.config)
    except ConfigError as exc:
        raise SystemExit(f"feedcheck: {exc}") from exc
    clocks = Clocks(sleep=time.sleep, monotonic=time.monotonic, now=_utc_now)
    checked_at = clocks.now()
    results = check_feeds(config, clocks)
    write_report(build_report(results, checked_at), args.output)
    if all_healthy(results):
        return EXIT_ALL_HEALTHY
    return EXIT_NOT_ALL_HEALTHY
